import { ConstraintTarget, getConstraintAttrName } from './constraintTarget.ts'

export type DrawMode = 'default' | 'origin' | 'bounds' | 'cards' | 'inherited'
export type CardGeometry = 'cross' | 'box' | 'fromTexture'

export const CARD_FACES = ['XPos', 'XNeg', 'YPos', 'YNeg', 'ZPos', 'ZNeg'] as const
export type CardFace = (typeof CARD_FACES)[number]

export type CardTextures = Record<CardFace, string | null>
export type Extent = [[number, number, number], [number, number, number]]

